  "questions": [
    {
      "source_id": "1",
      "stem": "A probe is located at the position \\(\\vec r = 5\\hat i - 12\\hat j\\), where distances are measured in meters. Which of the following statements is correct?",
      "options": [
        {
          "key": "A",
          "text": "The distance between the probe and the origin is \\(13\\,\\text{m}\\).",
          "is_correct": true,
          "explanation": "The distance from the origin is the magnitude of the position vector. Using \\(|\\vec r|=\\sqrt{x^2+y^2}=\\sqrt{5^2+(-12)^2}=\\sqrt{25+144}=\\sqrt{169}=13\\,\\text{m}\\), this statement is correct."
        },
        {
          "key": "B",
          "text": "The distance between the probe and the origin is \\(17\\,\\text{m}\\).",
          "is_correct": false,
          "explanation": "This comes from incorrectly adding the magnitudes of the components, \\(5+12\\), instead of using the Pythagorean theorem for vector magnitude."
        },
        {
          "key": "C",
          "text": "The distance between the probe and the origin is \\(12\\,\\text{m}\\).",
          "is_correct": false,
          "explanation": "This mistake treats the \\(y\\)-component alone as the full distance, but the magnitude depends on both components."
        },
        {
          "key": "D",
          "text": "None of the above is correct.",
          "is_correct": false,
          "explanation": "One of the listed values is correct: \\(|\\vec r|=13\\,\\text{m}\\). Therefore \"None of the above\" is not correct."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
      "skip_reason": "",
      "answer": "",
      "parts": []
    },
    {
      "source_id": "2",
      "stem": "If the displacement of an object is given by \\(\\vec s(t)=\\big((0.9\\,\\text{m/s}^3)t^3+(4.1\\,\\text{m/s}^2)t^2\\big)\\hat i\\), which of the following statements is correct?",
      "options": [
        {
          "key": "A",
          "text": "The magnitude of the acceleration at \\(t=0\\) is \\(0\\,\\text{m/s}^2\\).",
          "is_correct": false,
          "explanation": "This error assumes the acceleration must vanish at the initial time, but differentiating shows there is a nonzero constant term in \\(a(t)\\)."
        },
        {
          "key": "B",
          "text": "The magnitude of the acceleration at \\(t=0\\) is \\(8.2\\,\\text{m/s}^2\\).",
          "is_correct": true,
          "explanation": "Differentiate the displacement twice: \\(v(t)=\\frac{ds}{dt}=2.7t^2+8.2t\\) and \\(a(t)=\\frac{dv}{dt}=5.4t+8.2\\). Evaluating at \\(t=0\\) gives \\(a(0)=8.2\\,\\text{m/s}^2\\), so this statement is correct."
        },
        {
          "key": "C",
          "text": "This is a constant-acceleration motion.",
          "is_correct": false,
          "explanation": "This is incorrect because the second derivative is \\(a(t)=5.4t+8.2\\), which depends on time rather than remaining constant."
        },
        {
          "key": "D",
          "text": "The magnitude of the acceleration is \\(4.1\\,\\text{m/s}^2\\).",
          "is_correct": false,
          "explanation": "This confuses the coefficient of the \\(t^2\\) term in position with the acceleration. After taking two derivatives, the acceleration is not simply \\(4.1\\,\\text{m/s}^2\\)."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
      "skip_reason": "",
      "answer": "",
      "parts": []
    },
    {
      "source_id": "3",
      "stem": "An object takes \\(4.0\\,\\text{s}\\) to move from position \\(\\vec r_A = 7\\hat i - 2\\hat j\\) to position \\(\\vec r_B = -1\\hat i + 4\\hat j\\), where position is measured in meters. Which of the following statements is correct?",
      "options": [
        {
          "key": "A",
          "text": "The moving distance is \\(10\\,\\text{m}\\).",
          "is_correct": false,
          "explanation": "\\(10\\,\\text{m}\\) is the magnitude of the displacement, found from the endpoints, not necessarily the total path length traveled."
        },
        {
          "key": "B",
          "text": "The speed at \\(t=0\\) must be \\(2.5\\,\\text{m/s}\\).",
          "is_correct": false,
          "explanation": "This likely comes from dividing displacement magnitude by elapsed time, which gives at best an average rate based on endpoints, not the instantaneous speed at \\(t=0\\)."
        },
        {
          "key": "C",
          "text": "The acceleration at \\(t=0\\) must be \\(0.63\\,\\text{m/s}^2\\).",
          "is_correct": false,
          "explanation": "The initial acceleration cannot be determined uniquely from only the initial position, final position, and total elapsed time."
        },
        {
          "key": "D",
          "text": "None of the above is correct.",
          "is_correct": true,
          "explanation": "From the positions, the displacement is \\(\\Delta\\vec r = (-1-7)\\hat i + (4-(-2))\\hat j = -8\\hat i + 6\\hat j\\), whose magnitude is \\(|\\Delta\\vec r|=\\sqrt{(-8)^2+6^2}=10\\,\\text{m}\\). However, that value is the displacement magnitude, not necessarily the moving distance, and the initial speed and initial acceleration are not fixed by endpoint data alone, so none of the other statements must be true."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
      "skip_reason": "",
      "answer": "",
      "parts": []
    }
  ],
